cat > /tmp/q_meta.sql <<'SQL'
INSTALL httpfs; LOAD httpfs;
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;

-- q03: CAR total rows + distinct cod_imovel
.print === q03 CAR ===
SELECT count(*) AS n_rows, count(DISTINCT cod_imovel) AS n_distinct_ids
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');

-- q04: Trazo3 Goias row count
.print === q04 Trazo3 rowcount ===
SELECT count(*) AS n_rows
FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
SQL
timeout 600 duckdb -c ".read /tmp/q_meta.sql" 2>&1

cat > /tmp/q_meta2.sql <<'SQL'
INSTALL httpfs; LOAD httpfs;
.print === q04 geo metadata (EPSG) ===
SELECT key, value FROM parquet_kv_metadata('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet')
WHERE key = 'geo';
.print === facilities schema ===
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 1;
SQL
timeout 600 duckdb -c ".read /tmp/q_meta2.sql" 2>&1 | head -80

python3 - <<'PY'
import re
t=open('/home/runner/.claude/projects/-workspace/409ce9ba-01f8-4499-9682-d9aef046ac67/tool-results/blx397lve.txt').read()
# find EPSG in geo json
for m in re.finditer(r'EPSG[^"]*?(\d{4,5})', t):
    print("epsg-ref:", m.group(0)[:60])
for m in re.finditer(r'"?(?:crs|id|code)"?\s*[:=]\s*"?(\d{4,5})', t):
    print("code:", m.group(1))
# also just search for 4326 / 31982 etc
for c in ['4326','31982','31981','31983','5880','3857']:
    if c in t: print("contains", c)
PY

