input.command:
cd /tmp
cat > list_probe.sql <<'SQL'
CREATE OR REPLACE TABLE lst AS
SELECT * FROM read_csv('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);
.print === input row count ===
SELECT count(*) AS input_rows FROM lst;
.print === rows with/without cod_imovel ===
SELECT
  count(*) FILTER (WHERE cod_imovel IS NOT NULL AND cod_imovel <> '') AS rows_with_id,
  count(*) FILTER (WHERE cod_imovel IS NULL OR cod_imovel = '') AS rows_without_id,
  count(DISTINCT cod_imovel) FILTER (WHERE cod_imovel IS NOT NULL AND cod_imovel <> '') AS distinct_ids
FROM lst;
.print === rows with a geometry value ===
SELECT count(*) AS rows_with_geom FROM lst WHERE geometry IS NOT NULL AND geometry <> '';
.print === sample of id-less rows ===
SELECT * FROM lst WHERE cod_imovel IS NULL OR cod_imovel='' LIMIT 8;
.print === distinct municipios in list ===
SELECT count(DISTINCT municipio) AS n_muni FROM lst WHERE municipio IS NOT NULL AND municipio<>'';
SQL
timeout 120 duckdb -c ".read list_probe.sql" 2>&1
